00164     public function checkQuickpickJson()
00165     {
00166         global $bearsamppConfig;
00167 
00168         // Determine local file creation time or rebuild if missing
00169         $localFileCreationTime = $this->getLocalFileCreationTime();
00170 
00171         // Attempt to retrieve remote file headers
00172         $headers = get_headers(QUICKPICK_JSON_URL, 1);
00173         if (!$this->isValidHeaderResponse($headers)) {
00174             // If headers or Date are invalid, assume no update needed
00175             return false;
00176         }
00177 
00178         // Optionally log headers for verbose output
00179         $this->logHeaders($headers);
00180 
00181         // Compare the creation times (remote vs. local)
00182         $remoteFileCreationTime = strtotime(isset($headers['Date']) ? $headers['Date'] : '');
00183         if ($remoteFileCreationTime > $localFileCreationTime) { return $this->rebuildQuickpickJson(); }
00184 
00185         // Return false if local file is already up-to-date
00186         return false;
00187     }
