00194     private function getLocalFileCreationTime()
00195     {
00196         if (!file_exists($this->jsonFilePath)) {
00197             // If local file is missing, rebuild it immediately
00198             $this->rebuildQuickpickJson();
00199             return 0;
00200         }
00201         return filectime($this->jsonFilePath);
00202     }
