00238     public function getQuickpickJson(): array
00239     {
00240         $content = @file_get_contents( $this->jsonFilePath );
00241         if ( $content === false ) {
00242             Log::error( 'Error fetching content from JSON file: ' . $this->jsonFilePath );
00243 
00244             return ['error' => 'Error fetching JSON file'];
00245         }
00246 
00247         $data = json_decode( $content, true );
00248         if ( json_last_error() !== JSON_ERROR_NONE ) {
00249             Log::error( 'Error decoding JSON content: ' . json_last_error_msg() );
00250 
00251             return ['error' => 'Error decoding JSON content'];
00252         }
00253 
00254         return $data;
00255     }
