00263     public function rebuildQuickpickJson(): array
00264     {
00265         Log::debug( 'Fetching JSON file: ' . $this->jsonFilePath );
00266 
00267         // Fetch the JSON content from the URL
00268         $jsonContent = file_get_contents( QUICKPICK_JSON_URL );
00269 
00270         if ( $jsonContent === false ) {
00271             // Handle error if the file could not be fetched
00272             throw new Exception( 'Failed to fetch JSON content from the URL.' );
00273         }
00274 
00275         // Save the JSON content to the specified path
00276         $result = file_put_contents( $this->jsonFilePath, $jsonContent );
00277 
00278         if ( $result === false ) {
00279             // Handle error if the file could not be saved
00280             throw new Exception( 'Failed to save JSON content to the specified path.' );
00281         }
00282 
00283         // Return success message
00284         return ['success' => 'JSON content fetched and saved successfully'];
00285     }
