00295     public function getVersions(): array
00296     {
00297         Log::debug( 'Versions called' );
00298 
00299         $versions = [];
00300 
00301         $jsonData = $this->getQuickpickJson();
00302 
00303         foreach ( $jsonData as $entry ) {
00304             if ( is_array( $entry ) ) {
00305                 if ( isset( $entry['module'] ) && is_string( $entry['module'] ) ) {
00306                     if ( isset( $entry['versions'] ) && is_array( $entry['versions'] ) ) {
00307                         $versions[$entry['module']] = array_column( $entry['versions'], null, 'version' );
00308                     }
00309                 }
00310             }
00311             else {
00312                 Log::error( 'Invalid entry format in JSON data' );
00313             }
00314         }
00315 
00316         if ( empty( $versions ) ) {
00317             Log::error( 'No versions found' );
00318 
00319             return ['error' => 'No versions found'];
00320         }
00321 
00322         Log::debug( 'Found versions' );
00323 
00324         $this->versions = $versions;
00325 
00326         return $versions;
00327     }
