00372     public function checkDownloadId(): bool
00373     {
00374         global $bearsamppConfig;
00375 
00376         Log::debug( 'checkDownloadId method called.' );
00377 
00378         // Ensure the global config is available
00379         if ( !isset( $bearsamppConfig ) ) {
00380             Log::error( 'Global configuration is not set.' );
00381 
00382             return false;
00383         }
00384 
00385         $DownloadId = $bearsamppConfig->getDownloadId();
00386         Log::debug( 'DownloadId is: ' . $DownloadId );
00387 
00388         // Ensure the license key is not empty
00389         if ( empty( $DownloadId ) ) {
00390             Log::error( 'License key is empty.' );
00391 
00392             return false;
00393         }
00394 
00395         $url = QUICKPICK_API_URL . QUICKPICK_API_KEY . '&download_id=' . $DownloadId;
00396         Log::debug( 'API URL: ' . $url );
00397 
00398         // Attempt to fetch the API response
00399         // Note: If this fails, PHP will generate a warning which will be logged by the error handler
00400         // This is expected behavior when the API server is unavailable
00401         $response = file_get_contents( $url );
00402 
00403         // Check if the response is false
00404         if ( $response === false ) {
00405             Log::error( 'Failed to validate QuickPick license - API server unavailable' );
00406             return false;
00407         }
00408 
00409         Log::debug( 'API response: ' . $response );
00410 
00411         $data = json_decode( $response, true );
00412 
00413         // Check if the JSON decoding was successful
00414         if ( json_last_error() !== JSON_ERROR_NONE ) {
00415             Log::error( 'Error decoding JSON response: ' . json_last_error_msg() );
00416 
00417             return false;
00418         }
00419 
00420         // Validate the response data
00421         if ( isset( $data['success'] ) && $data['success'] === true && isset( $data['data'] ) && is_array( $data['data'] ) && count( $data['data'] ) > 0 ) {
00422             Log::debug( 'License key valid: ' . $DownloadId );
00423 
00424             return true;
00425         }
00426 
00427         Log::error( 'Invalid license key: ' . $DownloadId );
00428 
00429         return false;
00430     }
