00446     public function installModule(string $module, string $version): array
00447     {
00448         // Find the module URL and module name from the data
00449         $moduleUrl = $this->getModuleUrl( $module, $version );
00450 
00451         if ( is_array( $moduleUrl ) && isset( $moduleUrl['error'] ) ) {
00452             Log::error( 'Module URL not found for module: ' . $module . ' version: ' . $version );
00453 
00454             return ['error' => 'Module URL not found'];
00455         }
00456 
00457         if ( empty( $moduleUrl ) ) {
00458             Log::error( 'Module URL not found for module: ' . $module . ' version: ' . $version );
00459 
00460             return ['error' => 'Module URL not found'];
00461         }
00462 
00463         $state = HttpClient::checkInternetState();
00464         if ( $state ) {
00465             $response = $this->fetchAndUnzipModule( $moduleUrl, $module );
00466             Log::debug( 'Response is: ' . print_r( $response, true ) );
00467 
00468             // Check if enhanced mode is enabled
00469             global $bearsamppConfig;
00470             $enhancedMode = $bearsamppConfig->getEnhancedQuickPick();
00471 
00472             Log::debug('Enhanced mode: ' . ($enhancedMode ? 'enabled' : 'disabled'));
00473 
00474             // If installation was successful and enhanced mode is enabled, update config
00475             if (isset($response['success']) && $enhancedMode == 1) {
00476                 // Step 1: Update config FIRST (so reload can pick up the new version)
00477                 Log::debug('Enhanced mode enabled - Updating config for module: ' . $module . ' version: ' . $version);
00478                 $configUpdated = $this->updateModuleConfig($module, $version);
00479 
00480                 if ($configUpdated) {
00481                     // Step 2: Trigger reload AFTER config update (reload will apply the new version)
00482                     Log::debug('Config updated successfully, triggering reload to apply changes...');
00483 
00484                     // Send progress update to user - flush output
00485                     if (ob_get_level() > 0) {
00486                         ob_flush();
00487                     }
00488                     echo json_encode(['phase' => 'updating', 'message' => 'Updating system configuration...']) . PHP_EOL;
00489                     flush();
00490 
00491                     // Note: User must manually reload from tray menu to activate the new version
00492                     Log::debug('Installation complete - user must manually reload from tray menu');
00493                     $response['reload_required'] = true;
00494 
00495                     // Clear both disk and memory caches to ensure the UI shows correct icons and labels
00496                     Log::debug('Clearing caches after module installation...');
00497                     CacheManager::clearAll();
00498                 } else {
00499                     Log::error('Config update failed for module: ' . $module);
00500                     $response['reload_triggered'] = false;
00501                 }
00502             } else if (isset($response['success']) && $enhancedMode == 0) {
00503                 Log::debug('Enhanced mode disabled - skipping config update');
00504                 
00505                 // Even if not updating config, clear cache to be safe as new files were added
00506                 Log::debug('Clearing caches after module installation (Standard mode)...');
00507                 CacheManager::clearAll();
00508             }
00509 
00510             return $response;
00511         }
00512         else {
00513             Log::error( 'No internet connection available.' );
00514 
00515             return ['error' => 'No internet connection'];
00516         }
00517     }
