00527     public function fetchAndUnzipModule(string $moduleUrl, string $module): array
00528 {
00529     Log::debug("$module is: " . $module);
00530 
00531     global $bearsamppRoot, $bearsamppCore;
00532     $tmpDir = Path::getTmpPath();
00533     Log::debug('Temporary Directory: ' . $tmpDir);
00534 
00535     $fileName = basename($moduleUrl);
00536     Log::debug('File Name: ' . $fileName);
00537 
00538     $tmpFilePath = $tmpDir . '/' . $fileName;
00539     Log::debug('File Path: ' . $tmpFilePath);
00540 
00541     $moduleName = str_replace('module-', '', $module);
00542     Log::debug('Module Name: ' . $moduleName);
00543 
00544     // Find the correct module key by searching through the modules array
00545     // This handles proper capitalization for all module types
00546     $moduleKey = null;
00547     foreach ($this->modules as $key => $moduleInfo) {
00548         if (strtolower($key) === strtolower($moduleName)) {
00549             $moduleKey = $key;
00550             break;
00551         }
00552     }
00553 
00554     if (!$moduleKey) {
00555         Log::error("Module not found in modules array: $moduleName");
00556         return ['error' => 'Module configuration not found'];
00557     }
00558 
00559     $moduleType = $this->modules[$moduleKey]['type'];
00560     Log::debug('Module Type: ' . $moduleType);
00561 
00562     // Get module type
00563     $destination = $this->getModuleDestinationPath($moduleType, $moduleName);
00564     Log::debug('Destination: ' . $destination);
00565 
00566     // Retrieve the file path from the URL using the bearsamppCore module,
00567     // passing the module URL and temporary file path, with the use Progress Bar parameter set to true.
00568     $result = $bearsamppCore->getFileFromUrl($moduleUrl, $tmpFilePath, true);
00569 
00570     // Check if $result is false
00571     if ($result === false) {
00572         Log::error('Failed to retrieve file from URL: ' . $moduleUrl);
00573         return ['error' => 'Failed to retrieve file from URL'];
00574     }
00575 
00576     // Determine the file extension and call the appropriate unzipping function
00577     $fileExtension = pathinfo($tmpFilePath, PATHINFO_EXTENSION);
00578     Log::debug('File extension: ' . $fileExtension);
00579 
00580     if ($fileExtension === '7z' || $fileExtension === 'zip') {
00581         echo json_encode(['phase' => 'extracting']) . PHP_EOL;
00582         if (ob_get_length()) {
00583             ob_flush();
00584         }
00585         flush();
00586 
00587         $unzipResult = $bearsamppCore->unzipFile($tmpFilePath, $destination, function ($currentPercentage) {
00588             $progressStr = is_numeric($currentPercentage) ? "$currentPercentage%" : $currentPercentage;
00589             echo json_encode(['progress' => $progressStr]) . PHP_EOL;
00590             if (ob_get_length()) {
00591                 ob_flush();
00592             }
00593             flush();
00594         });
00595 
00596         if ($unzipResult === false) {
00597             return ['error' => 'Failed to unzip file. File: ' . $tmpFilePath . ' could not be unzipped', 'Destination: ' . $destination];
00598         }
00599     } else {
00600         Log::error('Unsupported file extension: ' . $fileExtension);
00601         return ['error' => 'Unsupported file extension'];
00602     }
00603 
00604     return ['success' => 'Module installed successfully'];
00605 }
