00619     public function getModuleDestinationPath(string $moduleType, string $moduleName)
00620     {
00621         global $bearsamppRoot;
00622         if ( $moduleType === 'application' ) {
00623             $destination = Path::getAppsPath() . '/' . strtolower( $moduleName ) . '/';
00624         }
00625         elseif ( $moduleType === 'binary' ) {
00626             $destination = Path::getBinPath() . '/' . strtolower( $moduleName ) . '/';
00627         }
00628         elseif ( $moduleType === 'tools' ) {
00629             $destination = Path::getToolsPath() . '/' . strtolower( $moduleName ) . '/';
00630         }
00631         else {
00632             $destination = '';
00633         }
00634 
00635         return $destination;
00636     }
