00680     private function updateModuleConfig(string $module, string $version): bool
00681     {
00682         try {
00683             $bearsamppConfig = new Config();
00684 
00685             // Remove 'module-' prefix if present and normalize the module name
00686             $moduleName = str_replace('module-', '', $module);
00687 
00688             // Find the correct module key by searching through the modules array
00689             // This handles proper capitalization for all module types
00690             $moduleKey = null;
00691             foreach ($this->modules as $key => $moduleInfo) {
00692                 if (strtolower($key) === strtolower($moduleName)) {
00693                     $moduleKey = $key;
00694                     break;
00695                 }
00696             }
00697 
00698             if (!$moduleKey) {
00699                 Log::error("Module not found in modules array: $moduleName");
00700                 return false;
00701             }
00702 
00703             $moduleType = $this->modules[$moduleKey]['type'];
00704 
00705             // Map module names to their config section names
00706             // For all types, use the lowercase name for the config key
00707             $configSection = strtolower($moduleKey);
00708 
00709             Log::debug("Updating config for module: $module (key: $moduleKey, type: $moduleType) to version: $version");
00710             Log::debug("Config section: $configSection");
00711 
00712             // Update the configuration file
00713             // The Config class expects a flat key like "nodejsVersion" not a section
00714             $configKey = $configSection . 'Version';
00715             $bearsamppConfig->replace($configKey, $version);
00716 
00717             Log::info("Successfully updated $configSection version to $version in bearsampp.conf");
00718 
00719             return true;
00720 
00721         } catch (Exception $e) {
00722             Log::error("Failed to update module config: " . $e->getMessage());
00723             return false;
00724         }
00725     }
